const gap=SizedBox(height:12);const head=TextStyle(fontSize:24,fontWeight:FontWeight.bold);String _d(DateTime d)=>'${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';String _t(DateTime d)=>'${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}';
